<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
require_role('admin');
function e_html($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
$userNama=$_SESSION['user']['nama']??'Admin'; $userRole=$_SESSION['user']['role']??'admin';
$namaHari=['Sunday'=>'Minggu','Monday'=>'Senin','Tuesday'=>'Selasa','Wednesday'=>'Rabu','Thursday'=>'Kamis','Friday'=>'Jumat','Saturday'=>'Sabtu'];
$namaBulan=[1=>'Januari',2=>'Februari',3=>'Maret',4=>'April',5=>'Mei',6=>'Juni',7=>'Juli',8=>'Agustus',9=>'September',10=>'Oktober',11=>'November',12=>'Desember'];
$todayLabel=($namaHari[date('l')]??date('l')).', '.date('d').' '.($namaBulan[(int)date('n')]??date('F')).' '.date('Y');
if(isset($_GET['export'])){ $tanggalExport=trim($_GET['tanggal']??''); if($tanggalExport!==''){ $stmtExport=$pdo->prepare("SELECT t.id_transaksi,t.tanggal,t.nama_pembeli,u.nama AS kasir,t.total,t.bayar,t.kembalian FROM transaksi t JOIN users u ON u.id=t.id_user WHERE DATE(t.tanggal)=? ORDER BY t.id_transaksi DESC"); $stmtExport->execute([$tanggalExport]); } else { $stmtExport=$pdo->query("SELECT t.id_transaksi,t.tanggal,t.nama_pembeli,u.nama AS kasir,t.total,t.bayar,t.kembalian FROM transaksi t JOIN users u ON u.id=t.id_user ORDER BY t.id_transaksi DESC"); } $exportRows=$stmtExport->fetchAll(); header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="data-transaksi.csv"'); $output=fopen('php://output','w'); fputcsv($output,['No','No. Transaksi','Tanggal','Pembeli','Kasir','Total','Bayar','Kembali']); $noExport=1; foreach($exportRows as $row){fputcsv($output,[$noExport++,$row['id_transaksi'],$row['tanggal'],$row['nama_pembeli'],$row['kasir'],$row['total'],$row['bayar'],$row['kembalian']]);} fclose($output); exit; }
$stmt=$pdo->query("SELECT t.id_transaksi,t.tanggal,t.nama_pembeli,t.id_user,t.total,t.bayar,t.kembalian,u.nama AS kasir FROM transaksi t JOIN users u ON u.id=t.id_user ORDER BY t.id_transaksi DESC"); $transaksi=$stmt->fetchAll();
?>
