<main class="main transaction-page"><section class="transaction-panel"><div class="transaction-head"><div><h1 class="transaction-title">DATA TRANSAKSI (ADMIN)</h1><p class="transaction-subtitle">Data seluruh transaksi penjualan koperasi.</p></div><div class="export-area"><div class="date-filter"><label for="tanggalExport">Tanggal Export</label><input type="date" id="tanggalExport"></div><button type="button" class="export-button" id="exportButton">Export CSV</button></div></div><div class="transaction-table-wrap"><table class="transaction-table"><thead><tr><th>No</th><th>No. Transaksi</th><th>Tanggal</th><th>Pembeli</th><th>Kasir</th><th>Total</th><th>Bayar</th><th>Kembali</th></tr></thead><tbody><?php if(!$transaksi): ?><tr><td colspan="8" class="empty">Belum ada transaksi.</td></tr><?php else: ?><?php foreach($transaksi as $i=>$row): ?><tr><td><?= $i+1 ?></td><td class="transaction-number">#<?= e_html($row['id_transaksi']) ?></td><td><?= e_html($row['tanggal']) ?></td><td><?= e_html($row['nama_pembeli']) ?></td><td><?= e_html($row['kasir']) ?></td><td class="transaction-total">Rp <?= number_format((float)$row['total'],0,',','.') ?></td><td>Rp <?= number_format((float)$row['bayar'],0,',','.') ?></td><td>Rp <?= number_format((float)$row['kembalian'],0,',','.') ?></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></section></main></section></div>
<script>const menuButton=document.querySelector('.menu-button'),sidebar=document.querySelector('.sidebar');if(menuButton&&sidebar){menuButton.addEventListener('click',function(){sidebar.classList.toggle('mobile-open')})}const exportButton=document.getElementById('exportButton'),tanggalExport=document.getElementById('tanggalExport');if(exportButton){exportButton.addEventListener('click',function(){let url='transaksi.php?export=1';if(tanggalExport&&tanggalExport.value!==''){url+='&tanggal='+encodeURIComponent(tanggalExport.value)}window.location.href=url})}</script></body></html>
